function conferencePlayoffGroups(){const teams=rank().filter(t=>!expansionPendingSeason(t)),names=[...new Set(teams.map(t=>t.conference))];return names.length===2&&names.every(n=>teams.filter(t=>t.conference===n).length>=8)?names.map(name=>({name,teams:teams.filter(t=>t.conference===name).slice(0,8)})):null}
const oldPlayoffField=playoffField,oldBracket=playoffBracket,oldOdds=playoffOdds,oldPlayoffSim=playoffs;
function usesConferencePlayoffs(){return !!conferencePlayoffGroups()&&!(state.champion!==null&&!state.history.some(g=>g.stage==='First round'))}
playoffGames=function(){return state.history.filter(g=>['First round','Conference semifinal','Conference final','Semifinal','Championship'].includes(g.stage))};
playoffField=function(){return usesConferencePlayoffs()?conferencePlayoffGroups().flatMap(g=>g.teams):oldPlayoffField()};
function firstRoundPairs(){return usesConferencePlayoffs()?conferencePlayoffGroups().flatMap(g=>[[0,7],[3,4],[2,5],[1,6]].map(([a,b])=>[g.teams[a].id,g.teams[b].id])):(()=>{const t=playoffField();return [[t[0].id,t[3].id],[t[1].id,t[2].id]]})()}
ownerPlayoffClub=function(t){return playoffField().some(p=>p.id===t.id)};
playoffs=function(){if(!usesConferencePlayoffs())return oldPlayoffSim();if(!gmCanAdvance()||state.day!==seasonLength()||state.champion!==null)return;ownerTrack();finalizeRegularAwards();const seeding=rank().map(t=>t.id),run=(ids,stage)=>{const ordered=[...ids].sort((a,b)=>seeding.indexOf(a)-seeding.indexOf(b));return play(ordered[0],ordered[1],stage).winner};let winners=firstRoundPairs().map(p=>run(p,'First round'));for(const stage of ['Conference semifinal','Conference final','Championship']){const next=[];for(let i=0;i<winners.length;i+=2)next.push(run(winners.slice(i,i+2),stage));winners=next}state.champion=winners[0];if(state.champion===controlledTeamId())state.titles++;ownerFinalize();say(state.teams[state.champion].city+' win the '+state.year+' championship!');save();render()};
playoffBracket=function(){if(!usesConferencePlayoffs())return oldBracket();const games=playoffGames();return `<section class="po-panel"><h2>PLAYOFF BRACKET · ${state.year}</h2><p>Eight seeds per conference · 1 vs 8, 4 vs 5, 3 vs 6, 2 vs 7</p><div class="conference-brackets">${conferencePlayoffGroups().map(group=>{let pairs=[[0,7],[3,4],[2,5],[1,6]].map(([a,b])=>[group.teams[a].id,group.teams[b].id]);return `<section><h3>${escapeHTML(group.name)} Conference</h3>${['First round','Conference semifinal','Conference final'].map(stage=>{const html=pairs.map(p=>{const game=games.find(g=>g.stage===stage&&p.includes(g.a)&&p.includes(g.b));return playoffMatch(p,stage.toUpperCase(),game)}).join('');const winners=pairs.map(p=>games.find(g=>g.stage===stage&&p.includes(g.a)&&p.includes(g.b))?.winner);pairs=[];for(let i=0;i<winners.length;i+=2)pairs.push(winners.slice(i,i+2));return `<div class="conference-round">${html}</div>`}).join('')}</section>`}).join('')}</div>${playoffMatch(games.find(g=>g.stage==='Championship')?[games.find(g=>g.stage==='Championship').a,games.find(g=>g.stage==='Championship').b]:[undefined,undefined],'CHAMPIONSHIP',games.find(g=>g.stage==='Championship'))}</section>`};
playoffOdds=function(){if(!usesConferencePlayoffs())return oldOdds();const teams=playoffField(),win=(a,b)=>1/(1+Math.exp((strength(b)-strength(a))/8));let groups=firstRoundPairs().map(p=>p.map(id=>({t:state.teams[id],chance:1})));let contenders=groups.map(pair=>pair.map(a=>({...a,chance:win(a.t,pair.find(b=>b!==a).t)})));while(contenders.length>1){const next=[];for(let i=0;i<contenders.length;i+=2){const a=contenders[i],b=contenders[i+1];next.push([...a.map(x=>({...x,chance:x.chance*b.reduce((s,y)=>s+y.chance*win(x.t,y.t),0)})),...b.map(x=>({...x,chance:x.chance*a.reduce((s,y)=>s+y.chance*win(x.t,y.t),0)}))])}contenders=next}return contenders[0].map(r=>({...r,chance:state.champion!==null?(r.t.id===state.champion?1:0):r.chance})).sort((a,b)=>b.chance-a.chance)};
const fieldViewBefore=playoffsView;playoffsView=function(){let html=fieldViewBefore();if(usesConferencePlayoffs())html=html.replace('<strong>4</strong><span>Top four league-wide</span>','<strong>16</strong><span>Eight per conference</span>').replace('Two rounds · Three games','Four rounds · Fifteen games').replace('Two semifinals. One championship game.','Two conference brackets. One championship.').replace('projected four-team field','projected 16-team field').replace('#1 vs #4 · #2 vs #3','Conference seeds: #1–#8 · #4–#5 · #3–#6 · #2–#7').replace('<strong>Semifinals</strong>','<strong>Conference rounds</strong>').replace('Semifinal winners · Winner takes the title','Conference champions · Winner takes the title');return html};
